(()=>{'use strict';const en=document.documentElement.lang==='en',L=(a,b)=>en?b:a,esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=v=>Number(v).toLocaleString(en?'en-US':'vi-VN',{maximumFractionDigits:2});
const types={unspecified:[L('Chưa xác định','Not specified'),L('So sánh các loại quạt tại cùng lưu lượng, áp suất và điều kiện không khí. Chọn theo đường đặc tính, độ ồn, không gian lắp đặt và hiệu suất tại điểm làm việc.','Compare fan types at the same airflow, pressure and air conditions. Select using performance curves, sound data, available space and efficiency at duty.')],centrifugal:[L('Quạt ly tâm','Centrifugal fan'),L('Dòng khí vào gần trục và thoát theo hướng xuyên tâm. Thường được cân nhắc cho tuyến có nhiều trở lực; kiểm tra kiểu cánh, độ sạch của khí, công suất trục và điều kiện cửa vào/ra.','Air enters near the axis and leaves radially. Often considered for higher-resistance paths; check wheel design, air cleanliness, shaft power and inlet/outlet conditions.')],axial:[L('Quạt hướng trục','Axial fan'),L('Dòng khí chủ yếu đi dọc trục. Kiểm tra cấu hình cánh hướng dòng, vùng vận hành ổn định, độ ồn và ảnh hưởng lắp đặt. Không giới hạn mọi quạt hướng trục vào ứng dụng áp suất thấp.','Air flows mainly along the axis. Check guide-vane configuration, stable operating range, sound and installation effects. Axial fans are not universally limited to low-pressure applications.')],mixed:[L('Quạt dòng hỗn hợp','Mixed-flow fan'),L('Dòng khí kết hợp hướng trục và xuyên tâm. Có thể phù hợp lắp nối ống; kiểm tra đặc tính thực tế, chiều dài lắp đặt và tổn thất đầu nối.','Air combines axial and radial motion. May suit inline installation; verify actual performance, installation length and connection losses.')]};
const applications={supply:[L('Cấp gió','Supply air'),L('Kiểm tra tổn thất lọc, coil, tiêu âm và miệng cấp; bổ sung tổn thất thiết bị thực tế vào tuyến.','Check filters, coils, silencers and supply outlets; add actual equipment losses to the path.')],exhaust:[L('Hút thải','Exhaust air'),L('Kiểm tra gió bù, cửa thải, van và điều kiện môi chất; đối chiếu khả năng chống ăn mòn nếu cần.','Check make-up air, discharge outlets, dampers and air contaminants; verify corrosion resistance where needed.')],pressurization:[L('Tăng áp','Pressurization'),L('Lưu lượng tuyến và áp suất chưa xác nhận khả năng tăng áp của không gian. Cần kiểm tra rò lọt, trạng thái cửa, chênh áp và phương án điều khiển theo thiết kế.','Path flow and pressure do not establish space pressurization performance. Check leakage, door states, pressure differential and control strategy against the design.')],smoke:[L('Hút khói','Smoke extraction'),L('Cần xác nhận chứng nhận, nhiệt độ và thời gian vận hành của quạt theo yêu cầu dự án. Phép tính này không mô phỏng cháy; tính chất không khí nhập phải phù hợp điều kiện thiết kế.','Verify fan certification, operating temperature and duration against project requirements. This calculation is not a fire simulation; entered air properties must match the design conditions.')],kitchen:[L('Hút bếp','Kitchen exhaust'),L('Kiểm tra khả năng xử lý khí có dầu mỡ, vệ sinh, vật liệu, vị trí động cơ, gió bù và tổn thất chụp hút/lọc. Loại quạt tự nó không xác nhận phù hợp hút bếp.','Check grease-laden air suitability, cleaning access, materials, motor location, make-up air and hood/filter losses. Fan type alone does not establish kitchen-exhaust suitability.')]};
function drawing(type){let shape;if(type==='centrifugal')shape='<path d="M205 38c-63 0-96 40-86 84s65 59 111 34l72-3V95h-62" fill="#dff0eb" stroke="#588e84" stroke-width="4"/><circle cx="195" cy="105" r="39" fill="#b6ddd2" stroke="#588e84" stroke-width="3"/><path d="M157 105h76M195 67v76M168 78l54 54M168 132l54-54" stroke="#588e84" stroke-width="5"/><path d="M75 105h42M266 124h80" stroke="#078774" stroke-width="4"/>';else if(type==='axial'||type==='mixed')shape='<rect x="120" y="45" width="160" height="120" rx="10" fill="#dff0eb" stroke="#588e84" stroke-width="4"/><circle cx="200" cy="105" r="45" fill="#b6ddd2" stroke="#588e84" stroke-width="3"/>'+(type==='axial'?'<path d="M200 105c-45-18-43-48-15-37 19 8 20 25 15 37M200 105c35-34 62-18 39 4-16 15-30 12-39-4M200 105c11 47-18 60-24 28-4-20 9-29 24-28" fill="#588e84"/>':'<path d="M173 77l53 56M173 133l53-56M175 78l15-9M225 132l-15 9" stroke="#588e84" stroke-width="7"/>')+'<path d="M65 105h42m-10-7 10 7-10 7M293 105h55m-10-7 10 7-10 7" fill="none" stroke="#078774" stroke-width="4"/>';else shape='<circle cx="200" cy="105" r="54" fill="#dff0eb" stroke="#588e84" stroke-width="4"/><path d="M200 73v64M168 105h64" stroke="#588e84" stroke-width="5"/>';return '<svg viewBox="0 0 420 190" role="img" aria-label="'+esc(types[type][0])+L(' — sơ đồ nguyên lý',' — schematic')+'">'+shape+'</svg>';}
window.HVACFanGuide={render(x,r){const type=types[x.fanType]?x.fanType:'unspecified',app=applications[x.application]?x.application:'supply';return '<section class="fan-selection-guide"><h3>'+L('Định hướng chọn quạt','Fan selection guidance')+'</h3><div class="fan-guide-layout">'+drawing(type)+'<div><strong>'+esc(types[type][0])+' · '+esc(applications[app][0])+'</strong><p>'+esc(types[type][1])+'</p></div></div><p>'+esc(applications[app][1])+'</p><p class="fan-duty">'+L('Điểm làm việc yêu cầu','Required duty')+': <strong>Q = '+n(x.flow)+' m³/h · '+L('Tổng áp','Total pressure')+' = '+n(r.total)+' Pa</strong><br>'+L('Áp suất tĩnh quạt tham khảo','Indicative fan static pressure')+': '+n(r.staticPressure)+' Pa</p><p class="field-help">'+L('Chọn đúng cơ sở áp suất của catalogue: tổng áp hoặc áp suất tĩnh quạt. Kiểu quạt và ứng dụng không tự thay hiệu suất, hệ số K hoặc công thức. Hiệu suất tổng áp đang nhập vẫn dùng cho công suất trục; đối chiếu tại điểm làm việc. Hình minh họa không theo tỷ lệ, không phải lựa chọn mã sản phẩm.','Match the catalogue pressure basis: fan total or fan static pressure. Type and application do not automatically change efficiency, K values or equations. Entered total-pressure efficiency still determines shaft power; verify it at duty. Illustrations are schematic and do not select a product model.')+'</p><a href="https://content.greenheck.com/public/DAMProd/Original/10002/Fan_Selection_Guide.pdf" target="_blank" rel="noopener noreferrer nofollow">'+L('Tham khảo: hướng dẫn chọn quạt Greenheck','Reference: Greenheck fan selection guide')+' ↗</a></section>';}};
})();
